function validate([n, offers]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (!Array.isArray(offers) || offers.length < 1 || offers.length > 100000) return 'offers needs 1 to 10^5 entries.';
  for (const offer of offers) {
    if (!Array.isArray(offer) || offer.length !== 3 || !offer.every(Number.isInteger)) return 'Each offer is [start, end, gold].';
    const [start, end, gold] = offer;
    if (start < 0 || start > end || end > n - 1) return 'Each offer needs 0 <= start <= end <= n - 1.';
    if (gold < 1 || gold > 1000) return 'Each gold value is between 1 and 1000.';
  }
  return null;
}

