function maximizeTheProfit(n, offers) {
  const byEnd = Array.from({ length: n }, () => []);
  for (const [start, end, gold] of offers) {
    byEnd[end].push([start, gold]);
  }

  const dp = new Array(n + 1).fill(0);
  for (let house = 0; house < n; house++) {
    dp[house + 1] = dp[house];
    for (const [start, gold] of byEnd[house]) {
      dp[house + 1] = Math.max(dp[house + 1], dp[start] + gold);
    }
  }
  return dp[n];
}

