function maximizeTheProfit(n, offers) {
  let best = 0;
  const m = offers.length;
  for (let mask = 0; mask < (1 << m); mask++) {
    const used = new Array(n).fill(false);
    let total = 0, ok = true;
    for (let i = 0; i < m && ok; i++) {
      if (!(mask & (1 << i))) continue;
      const [s, e, g] = offers[i];
      for (let h = s; h <= e; h++) {
        if (used[h]) { ok = false; break; }
        used[h] = true;
      }
      total += g;
    }
    if (ok && total > best) best = total;
  }
  return best;
}

