function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(1000, 100000);
    const m = 2000;
    const reach = rand() < 0.5 ? 50 : Math.max(1, Math.floor(n / 20));
    const offers = [];
    for (let i = 0; i < m; i++) {
      const start = int(0, n - 1);
      const end = Math.min(n - 1, start + int(0, reach));
      offers.push([start, end, int(1, 1000)]);
    }
    return [n, offers];
  }
  const n = int(1, 8);
  const m = int(1, 9);
  const top = rand() < 0.3 ? 3 : 20;
  const offers = [];
  for (let i = 0; i < m; i++) {
    const start = int(0, n - 1);
    const end = int(start, n - 1);
    offers.push([start, end, int(1, top)]);
  }
  return [n, offers];
}
